import './index.scss';
import { createVisTypeVislibVisFn } from './vis_type_vislib_vis_fn';
import { createPieVisFn } from './pie_fn';
import { createHistogramVisTypeDefinition, createLineVisTypeDefinition, createPieVisTypeDefinition, createAreaVisTypeDefinition, createHeatmapVisTypeDefinition, createHorizontalBarVisTypeDefinition, createGaugeVisTypeDefinition, createGoalVisTypeDefinition } from './vis_type_vislib_vis_types';
import { setFormatService, setDataActions, setOpenSearchDashboardsLegacy } from './services';

/** @internal */

/** @internal */

/** @internal */
export class VisTypeVislibPlugin {
  constructor(initializerContext) {
    this.initializerContext = initializerContext;
  }
  async setup(core, {
    expressions,
    visualizations,
    charts,
    visTypeXy
  }) {
    const visualizationDependencies = {
      uiSettings: core.uiSettings,
      charts
    };
    const vislibTypes = [createHistogramVisTypeDefinition, createLineVisTypeDefinition, createPieVisTypeDefinition, createAreaVisTypeDefinition, createHeatmapVisTypeDefinition, createHorizontalBarVisTypeDefinition, createGaugeVisTypeDefinition, createGoalVisTypeDefinition];
    const vislibFns = [createVisTypeVislibVisFn(), createPieVisFn()];

    // if visTypeXy plugin is disabled it's config will be undefined
    if (!visTypeXy) {
      const convertedTypes = [];
      const convertedFns = [];

      // Register legacy vislib types that have been converted
      convertedFns.forEach(expressions.registerFunction);
      convertedTypes.forEach(vis => visualizations.createBaseVisualization(vis(visualizationDependencies)));
    }

    // Register non-converted types
    vislibFns.forEach(expressions.registerFunction);
    vislibTypes.forEach(vis => visualizations.createBaseVisualization(vis(visualizationDependencies)));
  }
  start(core, {
    data,
    opensearchDashboardsLegacy
  }) {
    setFormatService(data.fieldFormats);
    setDataActions(data.actions);
    setOpenSearchDashboardsLegacy(opensearchDashboardsLegacy);
  }
}