import { i18n } from '@osd/i18n';
// @ts-ignore
import { vislibSlicesResponseHandler } from './vislib/response_handler';
export const createPieVisFn = () => ({
  name: 'opensearch_dashboards_pie',
  type: 'render',
  inputTypes: ['opensearch_dashboards_datatable'],
  help: i18n.translate('visTypeVislib.functions.pie.help', {
    defaultMessage: 'Pie visualization'
  }),
  args: {
    visConfig: {
      types: ['string'],
      default: '"{}"',
      help: ''
    }
  },
  fn(input, args) {
    const visConfig = JSON.parse(args.visConfig);
    const convertedData = vislibSlicesResponseHandler(input, visConfig.dimensions);
    return {
      type: 'render',
      as: 'visualization',
      value: {
        visData: convertedData,
        visType: 'pie',
        visConfig,
        params: {
          listenOnChange: true
        }
      }
    };
  }
});